package dev.emanoel.shopcore.auth;
import dev.emanoel.shopcore.exception.BusinessException; import dev.emanoel.shopcore.security.JwtService; import dev.emanoel.shopcore.user.*; import org.junit.jupiter.api.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AuthServiceTest { @Test void shouldRejectDuplicatedEmail(){var repo=mock(UserRepository.class);when(repo.existsByEmailIgnoreCase("john@example.com")).thenReturn(true);var service=new AuthService(repo,new BCryptPasswordEncoder(),mock(JwtService.class));assertThrows(BusinessException.class,()->service.register(new AuthDtos.RegisterRequest("John","john@example.com","password123")));} @Test void shouldRejectWrongPassword(){var repo=mock(UserRepository.class);var enc=new BCryptPasswordEncoder();when(repo.findByEmailIgnoreCase("john@example.com")).thenReturn(Optional.of(new User("John","john@example.com",enc.encode("correct123"),Role.CUSTOMER)));var service=new AuthService(repo,enc,mock(JwtService.class));assertThrows(BusinessException.class,()->service.login(new AuthDtos.LoginRequest("john@example.com","wrong")));} }
